import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    edge = [int(x) for x in data[1:1 + n]]
    w = [0] * n
    for i, e in enumerate(edge):
        if e >= 0:
            w[e] += i
    best = 0
    for v in range(n):
        if w[v] >= w[best]:
            best = v
    print(best)

